export type NeonToastMessageType = "error" | "info" | "warning" | "success" | undefined;
export type NeonToastButtonType = "primary" | "secondary" | "tertiary" | "borderless" | "utility" | "back-to-page";
export interface NeonToastButtonDetail {
    id: string;
    text: string;
    showText: string;
    click: () => void;
    type: NeonToastButtonType;
}
export interface NeonToastMessageDetail {
    heading: string;
    subheading?: string;
    type?: string;
    date?: Date | undefined;
    buttons: Array<NeonToastButtonDetail>;
    announceText?: string;
}
export interface NeonToastMessageConfig {
    sendTo: string;
    autoDismiss?: boolean;
    autoDismissTime?: number;
    messageType?: NeonToastMessageType | undefined;
}
export interface NeonToastMessageEventDetail {
    controlConfig: NeonToastMessageConfig;
    message: NeonToastMessageDetail;
    idCreatedCallback?: (id: string) => void;
}
